def magicalSum(m, k, nums):
    from collections import defaultdict
    MOD = 10**9 + 7
    n = len(nums)

    # Binomial coefficients C[a][b] for 0 <= b <= a <= m
    C = [[0] * (m + 1) for _ in range(m + 1)]
    for a in range(m + 1):
        C[a][0] = 1
        for b in range(1, a + 1):
            C[a][b] = (C[a - 1][b - 1] + C[a - 1][b]) % MOD

    # dp[(used, carry, ones)] = sum of weights
    dp = {(0, 0, 0): 1}
    for i in range(n):
        pw = [1] * (m + 1)
        for c in range(1, m + 1):
            pw[c] = pw[c - 1] * nums[i] % MOD
        ndp = defaultdict(int)
        for (used, carry, ones), val in dp.items():
            for c in range(m - used + 1):
                tot = carry + c
                no = ones + (tot & 1)
                nc = tot >> 1
                if no + bin(nc).count('1') > k:
                    continue
                key = (used + c, nc, no)
                ndp[key] = (ndp[key] + val * C[m - used][c] % MOD * pw[c]) % MOD
        dp = ndp

    ans = 0
    for (used, carry, ones), val in dp.items():
        if used == m and ones + bin(carry).count('1') == k:
            ans = (ans + val) % MOD
    return ans
